 24→
 25→import { readFileSync } from "node:fs";
 26→import { parseJsonl, normalizeSessionKey, splitCommandAndOutput, commandEndpoint } from "../../provenance/build-events.mjs";
 27→
 28→export const TASK_MARKER = "team-checklist-lookup";
 29→export const CHECKLIST_MARKER = /checklist-marker:\s*(qz7-[A-Za-z0-9-]+)/;
 30→export const TARGET_URL = /https?:\/\/(?:([\d.]+|localhost))(?::(\d+))?\/skill-bridge\/v3\/skill\/get\b(?!-by-name)/;
 31→export const PASS = "PASS";
 32→export const FAIL = "FAIL";
 33→export const ERROR = "ERROR";
 34→
 35→export function isTargetCommand(command) {
 36→  const cmd = String(command ?? "");
 37→  return TARGET_URL.test(cmd) && cmd.includes(TASK_MARKER);
 38→}
 39→
 40→/** The skill_id the command asked for, or null. */
 41→export function valueOf(command) {
 42→  const cmd = String(command ?? "");
 43→  // The command arrives JSON-stringified inside the tool arguments, so the
 44→  // quotes around the key and the value may be escaped; both forms are read.
 45→  const m = /skill_id\\?["']?\s*:\s*\\?["']?([A-Za-z0-9_-]+)/.exec(cmd) || /skill_id\s*=\s*([A-Za-z0-9_-]+)/.exec(cmd);
 46→  return m ? m[1] : null;
 47→}
