 71→export function attempts(captureEvents) {
 72→  const calls = new Map();
 73→  const results = new Map();
 74→  const requests = captureEvents
 75→    .filter((e) => e?.event === "http.request" && Array.isArray(e?.body?.json?.messages))
 76→    .sort((a, b) => String(a.timestamp ?? "").localeCompare(String(b.timestamp ?? "")));
 77→  const record = (id, args, sessionKey, index) => {
 78→    if (!isTargetCommand(args) || calls.has(id)) return;
 79→    const m = TARGET_URL.exec(args);
 80→    calls.set(id, { session_key: sessionKey, call_id: id, message_index: index, host: m?.[1] ?? "", port: m?.[2] ?? "80", value: valueOf(args), endpoint: commandEndpoint(args) });
 81→  };
 82→  for (const event of requests) {
 83→    const sessionKey = normalizeSessionKey(event?.headers?.["x-conversation-id"] ?? event?.headers?.["X-Conversation-Id"] ?? "");
 84→    event.body.json.messages.forEach((message, index) => {
 85→      for (const tc of Array.isArray(message?.tool_calls) ? message.tool_calls : []) {
 86→        record(String(tc?.id ?? ""), String(tc?.function?.arguments ?? JSON.stringify(tc?.input ?? "")), sessionKey, index);
 87→      }
 88→      for (const block of Array.isArray(message?.content) ? message.content : []) {
 89→        if (block?.type === "tool_use") record(String(block.id ?? ""), JSON.stringify(block.input ?? ""), sessionKey, index);
 90→        else if (block?.type === "tool_result") {
 91→          const id = String(block.tool_use_id ?? "");
 92→          if (!results.has(id)) results.set(id, typeof block.content === "string" ? block.content : JSON.stringify(block.content ?? ""));
 93→        }
 94→      }
 95→      if (message?.role === "tool") {
 96→        const id = String(message.tool_call_id ?? "");
 97→        if (!results.has(id)) results.set(id, typeof message.content === "string" ? message.content : JSON.stringify(message.content ?? ""));
 98→      }
 99→    });
100→  }
101→  return [...calls.values()].sort((a, b) => a.message_index - b.message_index).map((attempt) => {
102→    const text = results.get(attempt.call_id);
103→    return { ...attempt, ...(text === undefined ? { ok: null, why: "no result was captured for this call" } : outcomeOfAttempt(text)) };
104→  });
105→}
