119→export function render({ verdict, reason, attempts: tried }) {
120→  const lines = [`${verdict}  ${reason}`, ""];
121→  if (tried.length === 0) lines.push(`  no skill/get carrying the task marker (${TASK_MARKER}) appears in the capture`);
122→  else {
123→    lines.push(`  ${tried.length} attempt(s) at the target:`);
124→    for (const a of tried) lines.push(`    ${a.ok === true ? "ok  " : a.ok === false ? "fail" : "?   "} msg[${a.message_index}] get ${a.value ?? "?"} via ${a.host}:${a.port}  ${a.why}`);
125→  }
126→  return lines.join("\n");
127→}
